export type TranslationKey = keyof typeof translations;
export type Translate = (key: TranslationKey, values?: Record<string, string | number>) => string;

function readSavedLocale(): Locale {
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY);
    return locales.includes(saved as Locale) ? saved as Locale : "en";
  } catch {
    return "en";
  }
}

interface I18nValue { locale: Locale; setLocale: (locale: Locale) => void; t: Translate; intlLocale: string }
const defaultI18n: I18nValue = {
  locale: "en",
  setLocale: () => undefined,
  intlLocale: "en-US",
  t: (key, values) => {
    const message = translations[key]?.en ?? key;
    return values ? message.replace(/\{(\w+)\}/g, (match, name: string) => String(values[name] ?? match)) : message;
  },
};
const I18nContext = createContext<I18nValue>(defaultI18n);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(readSavedLocale);
  const setLocale = (next: Locale) => {
    setLocaleState(next);
    try { window.localStorage.setItem(STORAGE_KEY, next); } catch { /* Storage may be disabled; in-memory switching still works. */ }
  };
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const value = useMemo<I18nValue>(() => ({
    locale,
    setLocale,
    intlLocale: locale === "en" ? "en-US" : locale === "hi" ? "hi-IN" : "mr-IN",
    t: (key, values) => {
      const localized = translations[key]?.[locale] ?? translations[key]?.en ?? key;
      return values ? localized.replace(/\{(\w+)\}/g, (match, name: string) => String(values[name] ?? match)) : localized;
    },
  }), [locale]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  return useContext(I18nContext);
}

export function translateOrFallback(locale: Locale, key: string): string {
  const entry = (translations as Record<string, Partial<Record<Locale, string>>>)[key];
  if (entry) return entry[locale] ?? entry.en ?? key;

  for (const [template, values] of Object.entries(translations)) {
    const names: string[] = [];
    let expression = "^";
    let cursor = 0;
    for (const match of template.matchAll(/\{(\w+)\}/g)) {
      const index = match.index ?? 0;
      expression += template.slice(cursor, index).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(.+?)";
      names.push(match[1]);
      cursor = index + match[0].length;
    }
    if (!names.length) continue;
    expression += template.slice(cursor).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "$";
    const captured = key.match(new RegExp(expression));
    if (!captured) continue;
    const translated = values[locale] ?? values.en ?? template;
    const replacements = Object.fromEntries(names.map((name, index) => [name, captured[index + 1]]));
    return translated.replace(/\{(\w+)\}/g, (_placeholder, name: string) => replacements[name] ?? _placeholder);
  }
  return key;
}

export function translateMessage(locale: Locale, message: string): string {
  const exact = translateOrFallback(locale, message);
  if (exact !== message) return exact;
  const fieldMessage = message.match(/^([a-z_]+): (.+)$/i);
  if (fieldMessage) {
    const translatedValue = translateOrFallback(locale, fieldMessage[2]);
    if (translatedValue !== fieldMessage[2]) return `${fieldMessage[1]}: ${translatedValue}`;
  }
  const network = message.match(/^Network request to (.+) could not be completed\. Check the API URL, Vite proxy, network, or browser CORS settings\.$/);
  if (network) {
    return translateOrFallback(locale, "Network request to {endpoint} could not be completed. Check the API URL, Vite proxy, network, or browser CORS settings.").replace("{endpoint}", network[1]);
  }
  return message;
}

export function LanguageSelector() {
  const { locale, setLocale, t } = useI18n();
  return <label className="language-picker">
    <span>{t("Language")}</span>
    <select aria-label={t("Language")} value={locale} onChange={(event) => setLocale(event.target.value as Locale)}>
      <option value="en">English</option><option value="hi">हिंदी</option><option value="mr">मराठी</option>
    </select>
  </label>;
}
